#!/usr/bin/env python3
"""Recompute scoped teaching examples; check authored endpoints without rewriting."""
import copy,json,math
from pathlib import Path

def obj(i,k,l,role,config,n):
 return dict(id=i,kind=k,label=l,role=role,config=config,layout=dict(wide=dict(row=n//2,column=n%2,columnSpan=1),narrow=dict(row=n,column=0,columnSpan=1)))
def reg(i,l,n,typ='SCHEMATIC',unit=''):
 return obj(i,'register',l,'control',dict(type=typ,unit=unit),n)
def seq(i,l,n,slots,role='memory'):
 return obj(i,'sequence',l,role,dict(slots=slots,slotLabels=[str(x) for x in range(slots)]),n)
def rs(v,status='',**kw):return dict(value=v,status=status,**kw)
def ss(v,status=''):return dict(values=copy.deepcopy(v),status=status)
def metric(i,l,v,u):return dict(id=i,label=l,value=v,unit=u)
def step(i,t,e,states,result,metrics,kind=None,subjects=None,tokens=None):
 return dict(id=i,title=t,explanation=e,snapshot=dict(objects=copy.deepcopy(states),tokens=tokens or [],metrics=copy.deepcopy(metrics),activeConnections=[],result=result),transition=None if kind is None else dict(kind=kind,subjects=subjects or list(states),meaning=e))
def lesson(key,title,q,scope,family,objects,steps,invariants,**kw):
 return dict(schema=1,key='vol4:'+key,title=title,question=q,scope=scope,family=family,objects=objects,steps=steps,invariants=invariants,**kw)
def thermal():
 objects=[obj('heat','plot','Winding history and insulation threshold','output',dict(x=dict(min=0,max=4,label='Normalized thermal time',ticks=[0,1,2,3,4]),y=dict(min=0,max=2,label='Normalized temperature rise',ticks=[0,0.5,1,1.5,2])),0),reg('current','Burst current',1,unit='normalized current'),reg('margin','Remaining thermal margin',2,unit='normalized temperature rise')]
 def case(initial):
  # dT/dt = equilibrium - T, time normalized by thermal time constant.
  records=[(0,0,initial),(0,1,initial)];t=0;temp=initial
  for dt in [0.5,0.5]:
   t+=dt;temp=2+(temp-2)*math.exp(-dt);records.append((t,1,temp))
  records.append((t,0,temp));t+=1;temp=temp*math.exp(-1);records.append((t,0,temp))
  steps=[];history=[]
  titles=['Initial temperature persists','Apply a feasible current burst','Heat the winding for one interval','Continue the same current','Remove burst current','Cool with current removed']
  for n,(t,c,temp) in enumerate(records):
   point=[t,round(temp,5)]
   if not history or point!=history[-1]:history.append(point)
   states=dict(heat=dict(series=[dict(id='temperature',label='Winding rise',role='output',points=copy.deepcopy(history)),dict(id='limit',label='Insulation threshold',role='reference',points=[[0,1],[4,1]])],markers=[dict(id='now',x=t,y=round(temp,5),label='Current temperature')],status='Above threshold' if temp>1 else 'Below threshold'),current=rs(c),margin=rs(round(1-temp,5)))
   e=['A winding begins with retained thermal state.','Current changes immediately; temperature remains continuous.','The first-order thermal state integrates heating over a bounded interval.','The unchanged current continues generating heat.','Removing current stops the modeled heat input; it does not erase stored heat.','The winding loses heat toward ambient over one normalized time interval.'][n]
   steps.append(step('s'+str(n),titles[n],e,states,(['The winding retains its initial heat before the burst begins.','Current is on, but the winding has not instantaneously heated.','Stored heat has increased.' if temp<=1 else 'The warm winding has already crossed the insulation threshold.','The continuing burst crosses the threshold even though the current remains electrically feasible.','Current is off, but the winding remains above the insulation threshold.','Cooling reduces stored heat; removing current did not erase the thermal history.'][n]),[metric('age','Elapsed thermal time',t,'normalized time'),metric('hot','Above threshold',int(temp>1),'boolean')],None if n==0 else 'execute'))
  return steps
 return lesson('fig-02-motor-torque-speed-envelope','Thermal history limits a feasible burst','Why can the same electrically feasible current leave different thermal margins?','Dimensionless first-order thermal example, not the motor data sheet or a qualification model. Low-speed electrical feasibility is assumed. Ambient rise is zero, burst equilibrium is two, and the insulation threshold is one. Time is normalized by the thermal time constant.','curve',objects,case(0),['Temperature is continuous when current switches.','Removing current leaves stored heat; cooling takes time.','The thermal model does not replace the torque-speed voltage envelope.'],variants=[dict(id='warm',label='Warm initial winding',scope='Same first-order model and burst, with initial normalized temperature rise 0.6.',steps=case(0.6))])
def supply():
 count=8;arrival=2;expiry=5
 objects=[seq('stored','Capture-relative setpoints',0,count),seq('used','Executed setpoints',1,count,'output'),reg('clock','Evidence age',2,unit='toy ticks'),obj('gate','chamber','Next permission decision','control',dict(slots=2),3)]
 states=dict(stored=ss([None]*count),used=ss([None]*count),clock=rs(0),gate=ss([None,None]));steps=[]
 def add(n,title,e,kind=None):
  vals=states['stored']['values'];used=states['used']['values'];age=states['clock']['value'];available=sum(v is not None and j>=age and used[j] is None for j,v in enumerate(vals));steps.append(step('s'+str(n),title,e,states,(['Capture has started inference; no setpoints have arrived.','The received chunk keeps its future supply, but its elapsed prefix cannot execute.','The first admitted setpoint has executed; later setpoints remain stored.','The next admitted setpoint has executed while replacement inference is still unfinished.','The final evidence-valid setpoint has executed before the expiry tick.','Evidence has expired, so the next setpoint is denied despite the stored tail.','The unrenewed lease has also expired; stored data grant no authority.'][n]),[metric('available','Stored future setpoints',available,'setpoints'),metric('executed','Executed setpoints',sum(x is not None for x in used),'setpoints')],kind))
 add(0,'Capture an observation','Capture starts an independent evidence clock.')
 states['clock']=rs(arrival);states['stored']=ss(['elapsed']*arrival+['u'+str(j) for j in range(arrival,count)],'Prefix elapsed before arrival');states['gate']=ss(['evidence valid','lease valid']);add(1,'Receive the computed chunk','The capture-relative prefix has already elapsed and cannot be replayed.','reveal')
 for j in range(arrival,expiry):
  states['used']['values'][j]='u'+str(j);states['clock']=rs(j);add(len(steps),'Execute setpoint u'+str(j),'One admitted setpoint executes while replacement inference remains unfinished.','execute')
 states['clock']=rs(expiry);states['gate']=ss(['evidence expired','lease valid']);add(len(steps),'Deny execution at evidence expiry','The next permission check refuses the remaining chunk even though future setpoints remain stored.','write')
 states['clock']=rs(expiry+1);states['gate']=ss(['evidence expired','lease expired']);add(len(steps),'Expire the unrenewed lease','Time advances without a newly admitted replacement; fallback retains control.','execute')
 return lesson('fig-03-chunk-supply-horizon','Stored supply outlasts permission','Why can execution stop while the chunk still contains future setpoints?','Toy direct-replacement schedule with eight capture-relative slots, arrival at tick two, evidence expiry at tick five, and lease expiry at tick six. These abstract ticks do not replace the chapter clock or its machine parameters. No temporal ensembling is modeled.','sequence',objects,steps,['Elapsed setpoints are never replayed.','A further setpoint requires both valid evidence and a valid lease.','Stored supply cannot renew evidence or authority.'],checks=[dict(kind='metricEqualsNonNull',metric='executed',object='used')])
def kv():
 objects=[seq('context','Evaluation A: camera and instruction tokens',0,3,'input'),obj('cache','pool','Evaluation A KV cache','memory',dict(slots=5,columns=5,slotLabels=['p0','p1','p2','a0','free']),1),obj('compute','chamber','Current decode input and read operands','compute',dict(slots=7),2),seq('output','Sampled output tokens',3,2,'output')]
 states=dict(context=ss(['cam0','cam1','instruction']),cache=dict(slots=[None]*5,status='Owned by evaluation A'),compute=ss([None]*7),output=ss([None]*2));steps=[]
 def add(title,e,kind=None,tokens=None):
  steps.append(step('s'+str(len(steps)),title,e,states,(['Evaluation A owns an empty cache; its prompt is ready.','Prompt keys and values remain resident for later decode queries.','Output a0 exists, but its key and value are not yet in the cache.','Decode has consumed a0 and computed its current-token state.','Prompt KV remains resident while distinct read copies reach the decode workspace.','KV(a0) is now retained because a0 was consumed as an input.','Output a1 is sampled from the completed decode computation; it has not been cached.','Evaluation A has ended. Its released cache cannot carry into the next independent observation.'][len(steps)]),[metric('occupied','Retained KV positions',sum(v is not None for v in states['cache']['slots']),'positions')],kind,tokens=tokens))
 add('Begin one independent intent evaluation','The observation and instruction belong to evaluation A; its cache starts empty.')
 for j in range(3):states['cache']['slots'][j]=dict(value='KV(p'+str(j)+')',owner='Evaluation A',status='retained')
 add('Prefill the observation and instruction','One prefill processes all prompt positions and retains their keys and values.','execute')
 states['output']['values'][0]='a0';add('Sample the first output token','The prefill output supports sampling a0; a0 has not yet been consumed.','reveal')
 states['compute']=ss(['a0','q(a0)','KV(a0)',None,None,None,None]);add('Compute the next decode input state','Decode consumes a0 and computes its query, key, and value.','execute')
 states['compute']['values'][3:6]=['KV(p'+str(j)+')' for j in range(3)];tok=[dict(id='read'+str(j),label='KV(p'+str(j)+')',value='KV(p'+str(j)+')',role='input',owner='Evaluation A',at=dict(object='compute',index=3+j),state='copy',sourceAt=dict(object='cache',index=j)) for j in range(3)]
 add('Read retained prompt KV without eviction','The current query reads the prior prompt positions; every source cache cell remains retained.','copy',tok)
 states['cache']['slots'][3]=dict(value='KV(a0)',owner='Evaluation A',status='retained');add('Append the consumed input token KV','The cache grows by the key and value of a0, the current input token.','write')
 states['output']['values'][1]='a1';states['compute']['values'][6]='decode output';add('Sample the next output token','Attention over prior and current KV supplies the decode output used to sample a1.','execute')
 states['cache']['slots']=[None]*5;states['compute']=ss([None]*7);add('Finish evaluation A and release its KV','After the evaluation completes and all consumers finish, its cache is released. The next independent observation requires new prefill.','release')
 return lesson('fig-03-request-local-prefill-decode','Reuse KV within one intent evaluation','Which state survives a decode read, and when does its ownership end?','Schematic three-position camera/instruction prompt and two sampled tokens in one independent evaluation. KV means one position’s retained key/value pair across layers; tensor shapes and attention arithmetic are omitted.','cache',objects,steps,['Reading KV does not evict it.','A sampled output is appended only after it becomes a consumed decode input.','Independent observations do not inherit this evaluation’s KV.'],checks=[dict(kind='metricEqualsOccupied',metric='occupied',object='cache'),dict(kind='constantValues',object='context')])
def mailbox():
 objects=[seq('frame','Checked frame in MCU receive memory',0,2,'input'),seq('mailbox','MCU-local single-slot payload',1,2),reg('sequence','MCU publication sequence',2,'UINT','sequence'),seq('reader','Tick’s last validated payload',3,2,'output'),reg('authority','Authority remaining',4,unit='toy lease ticks')]
 old=['A0','A1'];new=['B0','B1'];sequence_start=8;lease_ticks=2;states=dict(frame=ss(new),mailbox=ss(old),sequence=rs(sequence_start),reader=ss(old),authority=rs(lease_ticks));steps=[]
 def add(title,e,kind=None):
  steps.append(step('s'+str(len(steps)),title,e,states,(['A complete received frame waits beside the old published mailbox and reader snapshot.','The odd counter forbids accepting the slot before its first payload cell changes.','The mailbox mixes old and new cells, so the odd counter forbids accepting it.','The interrupted tick retains the complete old proposal and does not spin.','The new payload is complete, but the odd counter still forbids acceptance.','The even counter publishes the completed payload; the reader still holds its old snapshot.','The reader now holds the whole new payload; consistency alone has not renewed authority.','Separate admission renews authority for the validated proposal.','The mailbox remains whole, but its authority has expired. Fallback controls execution.'][len(steps)]),[metric('complete','Payload cells matching new frame',sum(a==b for a,b in zip(states['mailbox']['values'],new)),'cells')],kind))
 add('Receive a checked frame beside the old mailbox','The transport has delivered a complete frame into MCU-owned receive memory. The tick retains its complete prior proposal under its existing lease; no AP/MCU memory is shared.')
 states['sequence']=rs(sequence_start+1);add('Mark the publication sequence odd','The writer marks the slot unavailable before mutating any payload cell.','write')
 states['mailbox']['values'][0]=new[0];add('Copy the first payload cell','The interrupt writer copies one cell while the sequence remains odd; this snapshot exposes the partial copy.','write')
 states['authority']=rs(lease_ticks-1);add('Reject one odd-sequence read attempt','A permission tick preempts the writer. Its one bounded attempt rejects the odd counter and retains the prior validated payload.','execute')
 states['mailbox']['values'][1]=new[1];add('Finish copying the payload','Both new payload cells are present, but the odd sequence still marks the slot unpublished.','write')
 states['sequence']=rs(sequence_start+2);add('Publish the even sequence','The interrupt writer completes publication after all payload writes.','write')
 states['reader']=ss(new);add('Accept a matching even read','One bounded tick read observes the same even sequence before and after copying. The reader retains the complete candidate; admission has not yet renewed its authority.','execute')
 states['authority']=rs(lease_ticks);add('Admit the validated proposal','A separate permission decision admits the complete fresh proposal and renews its lease. The even sequence alone was insufficient.','execute')
 states['authority']=rs(lease_ticks-lease_ticks);add('Expire authority during the proposer stall','No new frame or admission arrives. An unchanged even payload remains consistent while its lease expires and fallback takes control.','execute')
 return lesson('fig-04-multirate-cadence-buffer','Consistent data can lose authority','Why can a whole mailbox snapshot still become ineligible to execute?','MCU-local publication in event order, with two toy payload cells and abstract lease ticks. The AP sends framed transport; it does not share MCU memory. One tick makes one read attempt. Sequence numbers are identifiers, not timing.','ownership',objects,steps,['An odd sequence never replaces the reader’s last validated snapshot.','Payload copy completion precedes even publication.','Consistent repeated reads do not renew authority without a new admission.'])
def taps():
 objects=[seq('ap','Application processor: asked and mapped',0,2,'input'),seq('mcu','Safety MCU: received and enforced',1,2,'control'),seq('plant','Drive command and measured response',2,2,'output'),seq('log','Synchronized tap tuple: asked / mapped / enforced / measured',3,4),reg('target','Declared supervised target tap',4,'TAP')]
 asked=0.8;scale=0.5;limit=0.3;response=0.18;mapped=round(asked*scale,5);allowed=min(mapped,limit)
 states=dict(ap=ss([asked,None]),mcu=ss([None,None]),plant=ss([None,None]),log=ss([asked,None,None,None]),target=rs(None));steps=[]
 def add(title,e,kind=None):
  steps.append(step('s'+str(len(steps)),title,e,states,(['Only raw intent is available; mapping and permission have not occurred.','The mapped command differs from the requested action because the coordinate mapping changes its value.','The MCU has received the mapped proposal, but it has not yet enforced its limit.','The enforced command is lower than the mapped proposal because the permission path clamps it.','The drive receives the enforced command; response remains to be measured.','Measured response differs from the enforced command, preserving the evidence of tracking behavior.','The target explicitly names the enforced tap. Its provenance still requires curation before training.'][len(steps)]),[metric('recorded','Recorded tap values',sum(x is not None for x in states['log']['values']),'taps')],kind))
 add('Issue the raw request','A toy normalized request enters the unprivileged AP; its source is not an authority grant.')
 states['ap']['values'][1]=mapped;states['log']['values'][1]=mapped;add('Map the request into command coordinates','The declared scalar mapping multiplies the request by the toy conversion scale.','transform')
 states['mcu']['values'][0]=mapped;add('Deliver the framed command to MCU memory','Black-channel transport delivers the mapped command to a separate MCU-owned receive endpoint.','reveal')
 states['mcu']['values'][1]=allowed;states['log']['values'][2]=allowed;add('Clamp the command at the permission path','The toy amplitude bound limits the mapped proposal before dispatch. Passing this check does not certify expert demonstration quality.','transform')
 states['plant']['values'][0]=allowed;add('Dispatch the enforced command','The admitted command reaches the drives; plant response remains unmeasured.','write')
 states['plant']['values'][1]=response;states['log']['values'][3]=response;add('Measure the plant response over the aligned interval','The toy response is an independently declared observation, not a prediction from the scalar clamp.','reveal')
 states['target']=rs('enforced: '+str(allowed));add('Declare the supervised target tap','This diagnostic example selects the enforced tap for comparison only; provenance and curation must still decide training eligibility.','write')
 return lesson('fig-05-action-taps','One motion produces four distinct signals','Which causal stage supplies a supervised action target?','Toy scalar mapping and clamp in normalized illustrative coordinates, with a separately declared measured response. The source’s four synchronized taps and separate AP/MCU memories are retained. No physical response law or expert eligibility is inferred.','representation',objects,steps,['Asked, mapped, enforced, and measured signals have distinct identities.','Measured response can differ from the drive command.','Permission enforcement does not automatically make a record an expert target.'],checks=[dict(kind='metricEqualsNonNull',metric='recorded',object='log')])
def curation():
 slots=8;phases=['learner','learner','learner','blend','reorient','expert','expert','expert'];errors=[0,0.2,0.6,0.65,0.4,0.2,0.08,0]
 objects=[seq('trace','Fixed captured states by event index',0,slots,'input'),seq('commands','Recorded command provenance',1,slots,'input'),seq('states','State curation disposition',2,slots,'control'),seq('targets','Eligible expert action targets',3,slots,'output')]
 states=dict(trace=ss(errors),commands=ss(phases),states=ss(['pending']*slots),targets=ss([None]*slots));steps=[]
 def add(title,e,kind=None):
  steps.append(step('s'+str(len(steps)),title,e,states,(['All records remain pending; a takeover alone grants no expert label.','Divergent learner-visited states are retained for possible relabeling; their learner commands stay masked.','The blend is explicitly excluded from expert targets despite following takeover.','Operator reorientation remains excluded until measured stabilization.','The stabilized recovery segment is a review candidate, not yet an expert target.','Only the explicitly reviewed recovery commands become expert targets; earlier masks remain in force.'][len(steps)]),[metric('labels','Reviewed expert targets',sum(x is not None for x in states['targets']['values']),'samples')],kind))
 add('Inspect one fixed intervention trace','The toy trace has learner divergence, takeover blend, operator reorientation, and measured stabilization. Values are illustrative, not empirical drift data.')
 for j in [1,2]:states['states']['values'][j]='retain: relabel eligible'
 add('Retain the pre-takeover divergent states','The lookback includes learner-visited states that an expert may later relabel; learner commands remain excluded from expert targets.','write')
 states['states']['values'][0]='diagnostic learner';states['states']['values'][3]='excluded blend';add('Mask the controller blend','The enforcer’s transitional action remains diagnostic data with explicit provenance.','write')
 states['states']['values'][4]='excluded reorientation';add('Mask operator reorientation','A human takeover does not immediately create a stabilized expert demonstration.','write')
 for j in range(5,slots):states['states']['values'][j]='stabilized: awaiting review'
 add('Mark measured stabilization','Stabilization identifies a possible recovery segment; label eligibility still requires review.','write')
 for j in range(5,slots):states['states']['values'][j]='reviewed recovery';states['targets']['values'][j]='expert-'+str(j)
 add('Admit only the reviewed recovery segment','Explicit review admits the stabilized recovery commands while preserving all earlier masks.','write')
 return lesson('fig-05-compounding-error-flywheel','Takeover provenance determines label eligibility','Why does a takeover leave several nearby commands masked?','One fixed, eight-sample toy intervention trace in event order. Error values are illustrative normalized coordinates, not measured outcomes or a learning bound. Expert review is declared, not automated by the plot.','sequence',objects,steps,['Learner-visited states can be relabel eligible while their learner commands remain masked.','Blend and reorientation commands stay excluded from expert targets.','Stabilization precedes explicit review and admission of expert recovery.'],checks=[dict(kind='constantValues',object='trace'),dict(kind='constantValues',object='commands'),dict(kind='metricEqualsNonNull',metric='labels',object='targets')])
def diffusion():
 xs=[0,1,2,3,4];top=[0,0.75,1,0.75,0];bottom=[-x for x in top];noise=[0,-0.7,0.3,-0.5,0];weights=[0,0.5,0.8,1]
 objects=[obj('candidate','plot','AP candidate and fixed demonstrated modes','compute',dict(x=dict(min=0,max=4,label='Toy path coordinate',ticks=xs),y=dict(min=-1.2,max=1.2,label='Toy lateral coordinate',ticks=[-1,0,1])),0),seq('active','MCU: independently admitted chunk',1,4,'output'),reg('work','Dependent refinement evaluations completed',2,'COUNT','evaluations'),seq('received','MCU: received candidate, pending admission',3,5,'memory')]
 active=['u0','u1','u2','u3'];states=dict(active=ss(active),work=rs(0),received=ss([None]*5));steps=[]
 def path(w):return [[x,round((1-w)*n+w*y,5)] for x,n,y in zip(xs,noise,top)]
 def plot(w):return dict(series=[dict(id='upper',label='Demonstrated mode A',role='reference',points=list(map(list,zip(xs,top)))),dict(id='lower',label='Demonstrated mode B',role='reference',points=list(map(list,zip(xs,bottom)))),dict(id='mean',label='Regression mean (obstacle corridor)',role='control',points=[[0,0],[4,0]]),dict(id='proposal',label='Candidate only',role='compute',points=path(w))],markers=[dict(id='obstacle',x=2,y=0,label='Obstacle center; clearance unverified')],status='Candidate has no execution authority')
 states['candidate']=plot(weights[0])
 def add(title,e,kind=None):
  remaining=sum(x is not None for x in states['active']['values']);steps.append(step('s'+str(len(steps)),title,e,states,(['The noisy AP candidate has no authority; the MCU retains its separately admitted chunk.','The first refinement changes the candidate while the active MCU chunk remains intact.','The MCU has consumed u0; this does not admit or advance the AP candidate.','The next dependent evaluation refines the preceding candidate.','The MCU has consumed u1 while the AP candidate remains unadmitted.','Refinement has produced a coherent candidate, whose feasibility remains unverified.','The candidate has arrived in MCU memory pending admission. The old admitted chunk remains active.'][len(steps)]),[metric('remaining','Remaining active setpoints',remaining,'setpoints'),metric('evaluations','Dependent refinements',states['work']['value'],'evaluations')],kind))
 add('Hold a noisy candidate beside the admitted chunk','Two fixed demonstrated modes pass on opposite sides of a toy obstacle; their mean passes through its center.')
 states['candidate']=plot(weights[1]);states['work']=rs(states['work']['value']+1);add('Complete the first dependent refinement','A schematic fixed-seed interpolation moves the candidate toward one selected mode; it is not a diffusion solver.','execute')
 states['active']['values'][0]=None;add('Execute one already admitted setpoint','The MCU consumes u0 from its active chunk independently of unfinished AP candidate refinement.','execute')
 states['candidate']=plot(weights[2]);states['work']=rs(states['work']['value']+1);add('Complete the next dependent refinement','The next refinement consumes the preceding candidate, so its evaluation cannot run before that input exists.','execute')
 states['active']['values'][1]=None;add('Execute the next admitted setpoint','The active chunk keeps feeding the permission path while candidate computation spends renewal slack.','execute')
 states['candidate']=plot(weights[3]);states['work']=rs(states['work']['value']+1);add('Finish the candidate refinement','The final schematic candidate follows the selected demonstration mode; collision and actuator checks remain separate.','execute')
 states['received']=ss([p[1] for p in path(weights[3])],'Received candidate; admission pending');add('Deliver the candidate for independent admission','Transport places the candidate in MCU-owned memory. The active chunk is not replaced merely because a candidate arrived.','reveal')
 return lesson('fig-06-diffusion-denoising','Dependent refinement spends renewal slack','What changes while a new candidate is refined and an old chunk keeps executing?','Toy fixed-seed interpolation between a declared noisy path and one demonstrated mode, not the numerical diffusion algorithm or measured latency. Event order shows dependent evaluations and separately admitted execution; obstacle center alone does not model its extent.','schedule',objects,steps,['Each refinement consumes the previous candidate.','The MCU’s active chunk is distinct from the AP candidate.','Transport completion is not permission or active-buffer replacement.'],checks=[dict(kind='metricEqualsNonNull',metric='remaining',object='active'),dict(kind='nondecreasingMetric',metric='evaluations')])
def build():return [thermal(),supply(),kv(),mailbox(),taps(),curation(),diffusion()]
def main():
 p=Path(__file__).with_name('vol4-a.json')
 expected=build();actual=json.loads(p.read_text())
 # Full deterministic recomputation checks each derived occurrence, not just a final scalar.
 assert actual==expected,'Authored lesson drift: recomputed snapshots or explanatory contract differ'
 for l in actual:
  for name,steps in [('base',l['steps'])]+[(v['id'],v['steps']) for v in l.get('variants',[])]:
   s=steps[-1]
   print(l['key'],name,s['id'],json.dumps(s['snapshot']['metrics'],ensure_ascii=False))
 print('PASS: all thermal exponentials, slot counts, transforms, masks, path coordinates, sequence/lease states, and repeated derived occurrences recomputed.')
if __name__=='__main__':main()
